package pe.com.dentalamericana.booking;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import pe.com.dentalamericana.booking.dto.BookingDtos.*;import pe.com.dentalamericana.security.AuthenticatedUser;import java.util.List;
@RestController@RequestMapping("/api/v1")public class BookingController{private final BookingService service;public BookingController(BookingService service){this.service=service;}@PostMapping("/public/appointment-requests")@ResponseStatus(HttpStatus.CREATED)public BookingResponse create(@Valid@RequestBody PublicBookingRequestDto r,HttpServletRequest h){return service.create(r,h);}@GetMapping("/appointment-requests")@PreAuthorize("hasAuthority('CITA_LEER')")public List<BookingResponse>list(@RequestParam(required=false)BookingRequestStatus status){return service.list(status);}@PatchMapping("/appointment-requests/{id}")@PreAuthorize("hasAuthority('CITA_ESCRIBIR')")public BookingResponse manage(@PathVariable Long id,@Valid@RequestBody ManageBookingRequest r,@AuthenticationPrincipal AuthenticatedUser a,HttpServletRequest h){return service.manage(id,r,a,h);}}
